// src/components/Dashboard/ProjectView/ProjectQE.js
import React, { useEffect, useMemo, useState } from 'react';
// NOTE: import the PowerBI embed helper "similar to" your PBReactUI.js file:
import PowerBIEmbed from '../PBReactUI'; // assumes file at src/components/Dashboard/PBReactUI.js

/**
 * Props:
 *   project = { intake_number, intake_name }
 * Behavior:
 *   - Fetch the project's manual_cost & automation_cost using the EXISTING search endpoint
 *   - Ask backend for a Power BI filter payload that forces the embedded report
 *     to reflect these dynamic values
 *   - Pass { filters, metadata } to <PowerBIEmbed reportData={...} />
 */
export default function ProjectQE({ project }) {
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');
  const [reportData, setReportData] = useState(null);

  const label = useMemo(() => {
    return project ? `${project.intake_number} — ${project.intake_name}` : '';
  }, [project]);

  useEffect(() => {
    let abort = false;
    setErr('');
    setReportData(null);

    if (!project?.intake_number || !project?.intake_name) return;

    const fetchData = async () => {
      try {
        setLoading(true);

        // STEP 1: fetch the project row (uses existing endpoint; logic unchanged)
        // We search by intake_number (most precise) and then find the exact name match client-side
        const url = `http://localhost:5000/api/projects/search?query=${encodeURIComponent(
          String(project.intake_number)
        )}&limit=20`; // limit kept small
        const res = await fetch(url);
        const list = await res.json();

        // Find exact project (defensive: match both fields)
        const found =
          Array.isArray(list) &&
          list.find(
            (p) =>
              String(p.intake_number) === String(project.intake_number) &&
              String(p.intake_name) === String(project.intake_name)
          );

        if (!found) {
          throw new Error('Project not found in search results.');
        }

        // Expect manual_cost & automation_cost to be present per your instruction.
        // (If the endpoint returns more columns, great; otherwise these lines are no-ops.)
        const manual_cost =
          found.manual_cost != null ? Number(found.manual_cost) : undefined;
        const automation_cost =
          found.automation_cost != null ? Number(found.automation_cost) : undefined;

        if (
          typeof manual_cost !== 'number' ||
          Number.isNaN(manual_cost) ||
          typeof automation_cost !== 'number' ||
          Number.isNaN(automation_cost)
        ) {
          throw new Error(
            'manual_cost or automation_cost not available from /api/projects/search response.'
          );
        }

        // STEP 2: ask backend to shape a Power BI filter payload for these values
        const fUrl = `http://localhost:5000/api/powerbi/filters?manual_cost=${encodeURIComponent(
          manual_cost
        )}&automation_cost=${encodeURIComponent(automation_cost)}`;
        const fres = await fetch(fUrl);
        const fjson = await fres.json();
        if (!fres.ok || !Array.isArray(fjson?.filters)) {
          throw new Error('Failed to build Power BI filters on the server.');
        }

        if (abort) return;

        // Build the payload <PowerBIEmbed/> can use (filters + a little metadata)
        setReportData({
          filters: fjson.filters,
          meta: {
            project: label,
            manual_cost,
            automation_cost,
          },
        });
      } catch (e) {
        if (!abort) setErr(e.message || 'Failed to load report data.');
      } finally {
        if (!abort) setLoading(false);
      }
    };

    fetchData();
    return () => {
      abort = true;
    };
  }, [project, label]);

  if (!project) {
    return <div className="muted">Select a project to view QE dashboard.</div>;
  }

  if (loading) {
    return <div>Loading Project QE view for <b>{label}</b>…</div>;
  }

  if (err) {
    return (
      <div style={{ color: '#b91c1c' }}>
        Error loading Project QE data: {err}
      </div>
    );
  }

  // When filters are ready, render the report
  return (
    <div>
      <div className="muted" style={{ marginBottom: 8 }}>
        Dynamic data for <b>{label}</b> — manual_cost: <b>{reportData?.meta?.manual_cost}</b>, automation_cost:{' '}
        <b>{reportData?.meta?.automation_cost}</b>
      </div>
      <PowerBIEmbed reportData={reportData} />
    </div>
  );
}
